export function evaluate({ inputs, time }) {
  const u = inputs.launchSpeed, g = inputs.gravity, m = inputs.mass;
  const T = 2 * u / g, ta = u / g;
  const t = sdk.clamp(time, 0, T);
  const h = u * t - g * t * t / 2;
  const v = u - g * t;
  const apexH = u * u / (2 * g);
  const F = m * g;
  let st = 'Rising';
  if (time <= 0) st = 'Ready to toss';
  else if (Math.abs(t - ta) < 0.005) st = 'At the top';
  else if (t >= T - 1e-9) st = 'Back at launch height';
  else if (t > ta) st = 'Falling';
  const o = [];
  o.push(...sdk.panel({ id: 'lane.motion', x: 10, y: 34, w: 300, h: 370, title: 'The motion', state: st }));
  o.push(...sdk.panel({ id: 'lane.graph', x: 326, y: 34, w: 304, h: 370, title: 'Velocity over time', state: '' }));
  o.push(sdk.axis('axis.h', { x: 70, y: 380, length: 310, orientation: 'y', min: 0, max: 2.2, ticks: [0, 1, 2], label: 'Height', unit: 'm' }));
  const by = 380 - h / 2.2 * 310;
  o.push(sdk.circle('ball.toss', 130, by, 26));
  o.push(...sdk.vector('vec.v', { x: 130, y: by - 20 }, { value: v, direction: 'up' }, { scale: 8, label: 'v', role: 'observed' }));
  o.push(...sdk.vector('vec.a', { x: 160, y: by }, { value: -g, direction: 'up' }, { scale: 4, label: 'a', role: 'warning' }));
  o.push(...sdk.callout(200, 110, ['v = ' + sdk.format(v, 2) + ' m/s', 'a = ' + sdk.format(-g, 1) + ' m/s²', 'Fg = ' + sdk.format(F, 1) + ' N'], { id: 'callout.toss' }));
  const pts = sdk.sample(x => u - g * x, 0, T, 12).map(p => ({ x: p[0] * T / T, y: p[1] }));
  const cur = [];
  for (let i = 0; i <= 12; i++) { const x = t * i / 12; cur.push({ x, y: u - g * x }); }
  o.push(sdk.plot('plot.vt', { x: 340, y: 60, w: 285, h: 300, axes: { x: { label: 'Time', min: 0, max: 1.8, unit: 's' }, y: { label: 'v', min: -5.5, max: 5.5, unit: 'm/s' } }, series: [{ label: 'v = u - g t', kind: 'line', points: pts }, { label: 'so far', kind: 'line', points: cur }] }));
  o.push(sdk.text('plot.vt.note', 480, 392, 'slope a = -g', { role: 'warning' }));
  return { frame: { width: 640, height: 420, objects: o, readouts: [{ id: 'velocity', value: v }, { id: 'acceleration', value: -g }, { id: 'force', value: F }, { id: 'motionState', value: st }] }, quantities: { launchSpeed: u, gravity: g, mass: m, apexTime: ta, apexHeight: apexH, height: h, velocity: v, acceleration: -g, force: F } };
}
